import { useGetProjectGroupRevisionsForChatQuery } from '@/generated/graphql'
import { NEW_THREAD, useThreadId } from './store/threadStore'
import { MESSAGES_PER_PAGE } from '@/constants'
import { getMessagesFromRevisions } from './utils/get-messages-from-revisions'
import { useChatStore } from './store/chatStore'
import { Item } from './utils/types'
import { isStatusIndicatingRevisionIsBuilding } from './utils/project-revision'
import { useMemo } from 'react'

const getVariables = ({
	projectGroupId,
	threadId
}: {
	projectGroupId: string
	threadId: string | null
}) => ({
	projectGroupId,
	threadId,
	first: MESSAGES_PER_PAGE
})

export const useMessagesForChat = ({
	projectGroupId,
	isNewProjectGroup
}: {
	projectGroupId: string
	isNewProjectGroup: boolean
}) => {
	const threadId = useThreadId()
	const skipQuery =
		threadId === NEW_THREAD || !projectGroupId || projectGroupId === ''

	const submittingCommand = useChatStore(
		(state) => state.value.submittingCommand
	)
	const setIsGenerating = useChatStore((state) => state.setIsGenerating)

	const { data, fetchMore, subscribeToMore, loading } =
		useGetProjectGroupRevisionsForChatQuery({
			skip: skipQuery,
			fetchPolicy: isNewProjectGroup ? 'cache-only' : 'cache-and-network',
			variables: getVariables({
				projectGroupId,
				// @ts-expect-error - skipped if threadId is NEW_THREAD
				threadId
			}),
			onCompleted: (data) => {
				const latestRevision = data?.projectGroupById?.latestRevision
				const isGenerating = latestRevision?.status
					? isStatusIndicatingRevisionIsBuilding(latestRevision.status)
					: false
				if (threadId === NEW_THREAD) return
				setIsGenerating({ threadId, generating: isGenerating })
			}
		})

	const latestRevision = data?.projectGroupById?.latestRevision

	const shouldShowOptimistic =
		submittingCommand?.threadId === threadId ||
		(submittingCommand && !data?.projectGroupById?.revisions?.edges.length)

	const messages: Item[] = useMemo(() => {
		const edges = skipQuery ? [] : data?.projectGroupById?.revisions?.edges

		return getMessagesFromRevisions({
			edges: edges ?? [],
			latestRevision: latestRevision ?? undefined,
			submittingCommand: shouldShowOptimistic
				? submittingCommand.command
				: null,
			error: null,
			linkableElementSelected: false
		})
	}, [
		data?.projectGroupById?.revisions?.edges,
		latestRevision,
		shouldShowOptimistic,
		submittingCommand?.command,
		skipQuery
	])

	return { messages, fetchMore, subscribeToMore, loading, data }
}
